        for row in g:
            cnt.update(row)
        return cnt.most_common(1)[0][0]

    def components(g, bg):
        h, w = len(g), len(g[0])
        seen = [[False] * w for _ in range(h)]
        comps = []
        for r in range(h):
            for c in range(w):
                if not seen[r][c] and g[r][c] != bg:
                    q = deque([(r, c)])
                    seen[r][c] = True
                    cells = []
                    while q:
                        x, y = q.popleft()
                        cells.append((x, y, g[x][y]))
                        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < h and 0 <= ny < w and not seen[nx][ny] and g[nx][ny] != bg:
                                seen[nx][ny] = True
                                q.append((nx, ny))
                    comps.append(cells)
        return comps

