        cs = [c for r, c, v in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        h, w = r1 - r0 + 1, c1 - c0 + 1

        rel_cells = [(r - r0, c - c0, v) for r, c, v in cells]
        color_counts = Counter(v for _, _, v in rel_cells)
        main_color = color_counts.most_common(1)[0][0]

        markers = [(r, c, v) for r, c, v in rel_cells if v != main_color]
        pattern = [[None] * w for _ in range(h)]
        for r, c, v in rel_cells:
            pattern[r][c] = v

        return {
            "r0": r0, "c0": c0, "h": h, "w": w,
            "pattern": pattern,
            "markers": markers,
            "cell_count": len(cells),
